      const position = high === low ? 0 : clamp((value - low) / (high - low), 0, 1);
      values.set(`${output.instanceId}|${output.paramId}`, { value, position, unit: own.driven?.unit || own.parameter.unit || "", input: inputBase.value, offset, addition, rank, count, bias: wiring.instance, settings });
